<?php
 namespace Pterodactyl\Http\Controllers\Auth; use Ramsey\Uuid\Uuid; use Illuminate\Support\Str; use Illuminate\Http\Request; use Pterodactyl\Models\User; use Illuminate\Http\JsonResponse; use Pterodactyl\Facades\Activity; use Illuminate\Contracts\Hashing\Hasher; use Illuminate\Validation\ValidationException; use Pterodactyl\Services\Dezerx\Registration; use Pterodactyl\Services\Dezerx\Security\Security; use Pterodactyl\Notifications\AccountRegistered; class RegisterController extends AbstractLoginController { public function __construct(private Hasher $hasher) { parent::__construct(); } public function register(Request $request): JsonResponse { if (!Registration::enabled()) { abort(404); } $data = $this->validate($request, Registration::rules(), Registration::messages()); if (!Registration::allows($data['email'])) { $domains = Registration::domains(); throw ValidationException::withMessages([ 'email' => count($domains) === 1 ? 'Accounts here can only be made with an @' . $domains[0] . ' address.' : 'That email address is not one this panel accepts. Allowed: @' . implode(', @', $domains) . '.', ]); } $refusal = Security::refusal((string) $request->ip()); if ($refusal !== null) { throw ValidationException::withMessages(['username' => Security::message($refusal)]); } $user = new User([ 'username' => $data['username'], 'email' => $data['email'], 'name_first' => $data['name_first'] ?? Str::title($data['username']), 'name_last' => $data['name_last'] ?? $data['username'], 'root_admin' => false, 'language' => config('app.locale', 'en'), ]); $user->password = $this->hasher->make($data['password']); $user->uuid = Uuid::uuid4()->toString(); $user->save(); $user->notify(new AccountRegistered($user)); Activity::event('auth:register') ->withRequestMetadata() ->actor($user) ->subject($user) ->property(['username' => $user->username, 'email' => $user->email]) ->log(); Security::remember($user, $request->ip(), true); return $this->sendLoginResponse($user, $request); } } 